// GSAP's named eases as plain functions, so the ported HyperFrames blocks keep their exact motion on Remotion's
// frame clock (no GSAP at render time: one engine, safe for parallel frame rendering).
import { Easing, useCurrentFrame, useVideoConfig } from 'remotion';

export type Ease = (x: number) => number;
const c01 = (x: number) => Math.min(1, Math.max(0, x));
const pOut = (n: number): Ease => (x) => 1 - Math.pow(1 - x, n);
const pIn = (n: number): Ease => (x) => Math.pow(x, n);
const pInOut = (n: number): Ease => (x) => (x < 0.5 ? Math.pow(2, n - 1) * Math.pow(x, n) : 1 - Math.pow(-2 * x + 2, n) / 2);

export const E = {
  none: (x: number) => x,
  p1Out: pOut(2), p1In: pIn(2), p1InOut: pInOut(2),
  p2Out: pOut(3), p2In: pIn(3), p2InOut: pInOut(3),
  p3Out: pOut(4), p3In: pIn(4), p3InOut: pInOut(4),
  p4Out: pOut(5), p4In: pIn(5),
  expoOut: (x: number) => (x >= 1 ? 1 : 1 - Math.pow(2, -10 * x)),
  sineInOut: (x: number) => -(Math.cos(Math.PI * x) - 1) / 2,
  sineOut: (x: number) => Math.sin((Math.PI * x) / 2),
  backOut: (s = 1.70158): Ease => (x) => 1 + (s + 1) * Math.pow(x - 1, 3) + s * Math.pow(x - 1, 2),
  bezier: (a: number, b: number, c: number, d: number): Ease => Easing.bezier(a, b, c, d),
};

/** Progress 0..1 of a tween that starts at `at` and lasts `dur` seconds, with an ease. */
export const tw = (t: number, at: number, dur: number, ease: Ease = E.none) => ease(c01((t - at) / Math.max(1e-6, dur)));
/** a → b by progress p. */
export const mix = (a: number, b: number, p: number) => a + (b - a) * p;

/** Seconds since the enclosing Sequence started, plus the frame's scale unit (1 at 1920 px wide). */
export function useT() {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  return { t: frame / fps, u: width / 1920, width, height, fps };
}
