// Genovus brand for motion: colors, type, the official Egg and the wordmark (same proportions as the app's
// components/Wordmark.tsx: the egg is .677em × .867em, tipped -8°, overlapping the N and V).
import React from 'react';
import { continueRender, delayRender, Img, staticFile } from 'remotion';

export const C = {
  bg: '#0A0C10',
  panel: '#141821',
  panel2: '#1B202B',
  line: 'rgba(255,255,255,0.09)',
  text: '#F5F2ED',
  muted: '#A3A9B4',
  orange: '#FF8A1E',
  deep: '#F45A1B',
  sticky: '#FFD95A',
  ink: '#2B2620',
};
export const F = {
  display: '"Archivo Expanded", "Arial Black", sans-serif',
  body: 'Inter, "Segoe UI", Arial, sans-serif',
  mono: '"JetBrains Mono", Consolas, monospace',
  hand: 'Caveat, "Segoe Print", cursive',
};

const FACES: [string, string, string][] = [
  ['Archivo Expanded', 'archivo-expanded-latin-800.woff2', '800'],
  ['Inter', 'inter-latin-400-normal.woff2', '400'],
  ['Inter', 'inter-latin-500-normal.woff2', '500'],
  ['Inter', 'inter-latin-600-normal.woff2', '600'],
  ['JetBrains Mono', 'jetbrains-mono-latin-500.woff2', '500'],
  ['Caveat', 'caveat-600.woff2', '600'],
];
if (typeof document !== 'undefined') {
  const h = delayRender('brand fonts');
  Promise.all(FACES.map(([family, file, weight]) => new FontFace(family, `url(${staticFile(`fonts/${file}`)})`, { weight }).load().then((f) => document.fonts.add(f))))
    .then(() => continueRender(h))
    .catch((e) => { console.error(e); continueRender(h); });
}

export const EGG = staticFile('brand/genovus-egg.svg');

export function Egg({ size, style }: { size: number; style?: React.CSSProperties }) {
  return <Img src={EGG} style={{ width: size * 0.78, height: size, transform: 'rotate(-8deg)', filter: 'drop-shadow(0 6px 10px rgba(0,0,0,.5)) drop-shadow(0 0 18px rgba(244,90,27,.35))', ...style }} />;
}

/** The wordmark. `egg` (0–1) drops the egg in; `open` (0–1) slides GEN and VUS out from behind it. */
export function Wordmark({ size, egg = 1, open = 1 }: { size: number; egg?: number; open?: number }) {
  const slide = (1 - open) * size * 1.4;
  return (
    <div style={{ display: 'flex', alignItems: 'center', fontFamily: F.display, fontWeight: 800, fontSize: size, lineHeight: 1, letterSpacing: '0.01em', color: '#fff', whiteSpace: 'nowrap' }}>
      <span style={{ position: 'relative', zIndex: 0, transform: `translateX(${slide}px)`, opacity: open }}>GEN</span>
      <Img
        src={EGG}
        style={{
          position: 'relative', zIndex: 1, flex: 'none', width: '0.677em', height: '0.867em', margin: '0 -0.09em',
          transform: `translateY(${-0.03 * size - (1 - egg) * size * 2.5}px) rotate(${-8 - (1 - egg) * 30}deg)`, opacity: Math.min(1, egg * 3),
          filter: 'drop-shadow(0 .06em .08em rgba(0,0,0,.5)) drop-shadow(0 0 .14em rgba(244,90,27,.3))',
        }}
      />
      <span style={{ position: 'relative', zIndex: 0, transform: `translateX(${-slide}px)`, opacity: open }}>VUS</span>
    </div>
  );
}
