// Unedit Pro's cue layer: the graphics, sounds and camera moves the Cue Engine placed on the speaker's own words
// (gss-unedit lib/unedit-cues.ts). Every cue starts on its word, eases in with a spring, holds while it is being
// talked about, and gets out of the way. Graphics sit in the top 60% of the frame, clear of the captions.
//   counter   a glass card whose number rolls up to the figure said (prefix/suffix kept: $, %, ×)
//   logo      the Genovus egg and wordmark with a light sweep (other brands: their name, set in type, never a mark)
//   list      the items build one by one as each is said, each with a check
//   whip      the frame whips sideways with motion blur into the turn of the argument
//   question  a question card with an oversized serif "?"
//   tap       the real product screen, a finger-tap ripple on it
//   headline  the line hits as kinetic type, word by word
//   cta       the closing call to action, a bar with an arrow
// Camera moves wrap the shot layer: punch (a quick 12% push that holds), push (a slow 6% creep), pull (back out),
// shake (a short decaying jolt), whip (sideways blur). Sounds play from named slots in public-pro/sfx.
import React from 'react';
import { AbsoluteFill, Audio, Img, interpolate, OffthreadVideo, Sequence, spring, staticFile, useCurrentFrame, useVideoConfig } from 'remotion';
import { F } from './brand';
import { LightLeak } from '@remotion/light-leaks';
import { CameraMotionBlur } from '@remotion/motion-blur';
import { evolvePath } from '@remotion/paths';
import { noise2D } from '@remotion/noise';
import { fitText } from '@remotion/layout-utils';
import { ArrowRight, Check, Clock, DollarSign, Hand, MessageCircleQuestion, Percent, TrendingUp, icons } from 'lucide-react';

export type ProCue = {
  t: number; end: number; kind: 'counter' | 'logo' | 'list' | 'whip' | 'question' | 'tap' | 'headline' | 'cta' | 'icon'; text: string; icon?: string;
  items?: { text: string; t: number }[]; value?: number; prefix?: string; suffix?: string;
  screen?: { still: string; clip?: string | null; wide?: boolean } | null; sound: string | null; cam: 'punch' | 'push' | 'pull' | 'shake' | 'whip' | null;
};

export const ACCENT = '#FF6A2B';
export const GOLD = '#FFA31A';
export const SERIF = '"Instrument Serif", Georgia, serif';
export const GLASS: React.CSSProperties = { background: 'rgba(14,16,22,.58)', backdropFilter: 'blur(22px) saturate(1.3)', WebkitBackdropFilter: 'blur(22px) saturate(1.3)', border: '1.5px solid rgba(255,255,255,.16)', boxShadow: '0 40px 90px -20px rgba(0,0,0,.65), inset 0 1px 0 rgba(255,255,255,.18)' };

function useIn(delay = 0) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  return spring({ frame: frame - delay, fps, config: { damping: 15, stiffness: 170, mass: 0.75 } });
}
/** Out: the last 8 frames of the cue fade and lift away. */
function useOut(durFrames: number) {
  const frame = useCurrentFrame();
  return interpolate(frame, [durFrames - 8, durFrames], [1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
}

/** A slow organic drift (a few pixels) so glass cards float instead of sitting dead still. */
function useDrift(seed: string, amp = 5) {
  const frame = useCurrentFrame();
  return `translate(${(noise2D(seed, frame / 90, 0) * amp).toFixed(2)}px, ${(noise2D(seed, 0, frame / 90) * amp).toFixed(2)}px)`;
}

/** A marker stroke that draws itself under a word (a hand-drawn swoosh, Genovus orange). */
export function Marker({ width, delay = 4, color = ACCENT }: { width: number; delay?: number; color?: string }) {
  const frame = useCurrentFrame();
  const p = interpolate(frame, [delay, delay + 12], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: (x) => 1 - Math.pow(1 - x, 3) });
  const d = `M 6 22 C ${width * 0.3} 6, ${width * 0.6} 30, ${width - 6} 12`;
  const { strokeDasharray, strokeDashoffset } = evolvePath(p, d);
  return (
    <svg width={width} height={36} viewBox={`0 0 ${width} 36`} style={{ display: 'block', margin: '0 auto', overflow: 'visible' }}>
      <path d={d} fill="none" stroke={color} strokeWidth={10} strokeLinecap="round" strokeDasharray={strokeDasharray} strokeDashoffset={strokeDashoffset} />
    </svg>
  );
}

/** The icon for a counter: money, percent, time, else a rising line. */
function CounterIcon({ cue }: { cue: ProCue }) {
  const props = { size: 64, color: ACCENT, strokeWidth: 2.4 };
  if (cue.prefix === '$') return <DollarSign {...props} />;
  if (cue.suffix === '%') return <Percent {...props} />;
  if (/\b(sec|min|hour|hr|day|week|month|year)/i.test(cue.text)) return <Clock {...props} />;
  return <TrendingUp {...props} />;
}

/** Film grain: a faint texture over the whole frame (a filmic finish, never visible as noise). One pre-made tile,
 *  shifted every frame so it lives, costs nothing to render (public-pro/fx/grain.png). */
export function Grain() {
  const frame = useCurrentFrame();
  const x = (frame * 197) % 512, y = (frame * 331) % 512;
  return <AbsoluteFill style={{ pointerEvents: 'none', mixBlendMode: 'overlay', opacity: 0.1, backgroundImage: `url(${staticFile('fx/grain.png')})`, backgroundRepeat: 'repeat', backgroundPosition: `${x}px ${y}px` }} />;
}

function fmt(n: number, final: number): string {
  const decimals = Number.isInteger(final) ? 0 : 1;
  return n.toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
}

function Counter({ cue, dur }: { cue: ProCue; dur: number }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = useIn();
  const out = useOut(dur);
  const roll = interpolate(frame, [2, Math.round(fps * 0.9)], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: (x) => 1 - Math.pow(1 - x, 3) });
  const v = cue.value ?? 0;
  const drift = useDrift('counter');
  return (
    <div style={{ position: 'absolute', left: 90, right: 90, top: 250, borderRadius: 44, padding: '34px 40px 40px', textAlign: 'center', ...GLASS, opacity: out, transform: `${drift} translateY(${interpolate(p, [0, 1], [70, 0])}px) scale(${interpolate(p, [0, 1], [0.9, 1])})` }}>
      <div style={{ display: 'grid', placeItems: 'center', marginBottom: 6, transform: `scale(${p}) rotate(${interpolate(p, [0, 1], [-40, 0])}deg)` }}><CounterIcon cue={cue} /></div>
      <div style={{ fontFamily: F.display, fontWeight: 800, fontSize: String(Math.round(v)).length > 5 ? 150 : 200, lineHeight: 1, color: '#fff', letterSpacing: '-0.03em', fontVariantNumeric: 'tabular-nums', textShadow: `0 0 60px ${ACCENT}55` }}>
        <span style={{ color: GOLD }}>{cue.prefix}</span>{fmt(v * roll, v)}<span style={{ color: GOLD }}>{cue.suffix}</span>
      </div>
      <Marker width={420} delay={Math.round(fps * 0.85)} color={GOLD} />
      {cue.text ? <div style={{ marginTop: 14, fontFamily: SERIF, fontStyle: 'italic', fontSize: 64, color: ACCENT, lineHeight: 1.1 }}>{cue.text.toLowerCase()}</div> : null}
    </div>
  );
}

function Logo({ cue, dur }: { cue: ProCue; dur: number }) {
  const frame = useCurrentFrame();
  const p = useIn();
  const out = useOut(dur);
  const genovus = /genovus/i.test(cue.text) || !cue.text;
  const sweep = interpolate(frame, [4, 22], [-40, 140], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const name = genovus ? 'GENOVUS' : cue.text.toUpperCase();
  return (
    <div style={{ position: 'absolute', left: 0, right: 0, top: 300, display: 'grid', placeItems: 'center', opacity: out }}>
      <div style={{ ...GLASS, borderRadius: 999, padding: '30px 64px', display: 'flex', alignItems: 'center', gap: 26, transform: `scale(${interpolate(p, [0, 1], [0.7, 1])})`, overflow: 'hidden', position: 'relative' }}>
        {genovus ? <Img src={staticFile('brand/genovus-egg.svg')} style={{ width: 84, height: 104, transform: `rotate(${interpolate(p, [0, 1], [-25, 0])}deg)` }} /> : null}
        <span style={{ fontFamily: F.display, fontWeight: 800, fontSize: 92, letterSpacing: `${interpolate(p, [0, 1], [0.4, 0.06])}em`, color: '#fff' }}>{name}</span>
        <div style={{ position: 'absolute', top: 0, bottom: 0, left: `${sweep}%`, width: '22%', background: 'linear-gradient(100deg, transparent, rgba(255,255,255,.35), transparent)', transform: 'skewX(-18deg)' }} />
      </div>
    </div>
  );
}

function List({ cue, dur, t0 }: { cue: ProCue; dur: number; t0: number }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const out = useOut(dur);
  const p = useIn();
  return (
    <div style={{ position: 'absolute', left: 80, right: 80, top: 210, borderRadius: 40, padding: '36px 44px', ...GLASS, opacity: out * p, display: 'grid', gap: 22 }}>
      {(cue.items ?? []).map((it, i) => {
        const at = Math.max(0, Math.round((it.t - t0) * fps));
        const q = spring({ frame: frame - at, fps, config: { damping: 14, stiffness: 180 } });
        return (
          <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 24, opacity: q, transform: `translateX(${interpolate(q, [0, 1], [-60, 0])}px)` }}>
            <span style={{ width: 62, height: 62, borderRadius: 18, background: ACCENT, display: 'grid', placeItems: 'center', fontFamily: F.display, fontWeight: 800, fontSize: 34, color: '#111', transform: `scale(${q})` }}>{i + 1}</span>
            <span style={{ fontFamily: F.display, fontWeight: 800, fontSize: 56, color: '#fff', textTransform: 'uppercase', lineHeight: 1.05, flex: 1 }}>{it.text}</span>
            <Check size={54} color={GOLD} strokeWidth={3} style={{ opacity: spring({ frame: frame - at - 8, fps, config: { damping: 12 } }) }} />
          </div>
        );
      })}
    </div>
  );
}

function Question({ cue, dur }: { cue: ProCue; dur: number }) {
  const p = useIn();
  const out = useOut(dur);
  return (
    <div style={{ position: 'absolute', left: 80, right: 80, top: 230, borderRadius: 44, padding: '20px 44px 44px', ...GLASS, opacity: out, transform: `translateY(${interpolate(p, [0, 1], [-50, 0])}px)` }}>
      <div style={{ fontFamily: SERIF, fontStyle: 'italic', fontSize: 260, lineHeight: 0.9, color: ACCENT, transform: `rotate(${interpolate(p, [0, 1], [-30, -6])}deg)`, transformOrigin: 'left bottom', display: 'inline-block' }}>?</div>
      <div style={{ position: 'absolute', right: 40, top: 40, opacity: p }}><MessageCircleQuestion size={72} color={ACCENT} strokeWidth={2.2} /></div>
      <div style={{ fontFamily: F.display, fontWeight: 800, fontSize: 66, color: '#fff', textTransform: 'uppercase', lineHeight: 1.08 }}>{cue.text}</div>
    </div>
  );
}

function Tap({ cue, dur }: { cue: ProCue; dur: number }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = useIn();
  const out = useOut(dur);
  const tapAt = Math.round(fps * 0.45);
  const ring = interpolate(frame, [tapAt, tapAt + 16], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const press = frame >= tapAt && frame < tapAt + 6 ? 0.92 : 1;
  const s = cue.screen;
  const fit: React.CSSProperties = { width: '100%', height: '100%', objectFit: 'cover', objectPosition: s?.wide ? 'left top' : 'top' };
  return (
    <div style={{ position: 'absolute', left: 120, right: 120, top: 150, height: 1080, borderRadius: 48, overflow: 'hidden', ...GLASS, opacity: out, transform: `translateY(${interpolate(p, [0, 1], [120, 0])}px) scale(${interpolate(p, [0, 1], [0.92, press])})` }}>
      {s ? (s.clip ? <OffthreadVideo src={s.clip} muted style={fit} /> : <Img src={s.still} style={fit} />) : null}
      <div style={{ position: 'absolute', left: '50%', top: '62%', width: 120, height: 120, marginLeft: -60, marginTop: -60, borderRadius: '50%', border: `6px solid ${ACCENT}`, opacity: 1 - ring, transform: `scale(${0.4 + ring * 1.8})` }} />
      <div style={{ position: 'absolute', left: '50%', top: '62%', width: 64, height: 64, marginLeft: -32, marginTop: -32, borderRadius: '50%', background: 'rgba(255,255,255,.85)', boxShadow: `0 0 0 10px ${ACCENT}55`, opacity: interpolate(frame, [tapAt - 6, tapAt, tapAt + 14], [0, 1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }) }} />
      <div style={{ position: 'absolute', left: '50%', top: '62%', marginLeft: -6, marginTop: 4, transform: `translate(${interpolate(frame, [0, tapAt], [140, 0], { extrapolateRight: 'clamp' })}px, ${interpolate(frame, [0, tapAt], [160, 0], { extrapolateRight: 'clamp' })}px) scale(${press})`, filter: 'drop-shadow(0 10px 20px rgba(0,0,0,.5))' }}><Hand size={110} color="#fff" fill="rgba(255,255,255,.15)" strokeWidth={1.6} /></div>
    </div>
  );
}

function Headline({ cue, dur }: { cue: ProCue; dur: number }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const out = useOut(dur);
  const words = cue.text.split(' ');
  return (
    <div style={{ position: 'absolute', left: 70, right: 70, top: 300, textAlign: 'center', opacity: out, display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: '0 26px' }}>
      {words.map((w, i) => {
        const q = spring({ frame: frame - i * 3, fps, config: { damping: 12, stiffness: 220, mass: 0.6 } });
        const hot = i === words.length - 1;
        return (
          <span key={i} style={{ fontFamily: hot ? SERIF : F.display, fontStyle: hot ? 'italic' : 'normal', fontWeight: hot ? 400 : 800, fontSize: hot ? 170 : 130, lineHeight: 1.02, textTransform: hot ? 'none' : 'uppercase', color: hot ? ACCENT : '#fff', opacity: q, display: 'inline-block', transform: `translateY(${interpolate(q, [0, 1], [80, 0])}px) scale(${interpolate(q, [0, 1], [1.4, 1])})`, textShadow: '0 10px 40px rgba(0,0,0,.6)' }}>
            {hot ? w.toLowerCase() : w}
            {hot ? <Marker width={Math.min(560, 70 + w.length * 70)} delay={i * 3 + 8} /> : null}
          </span>
        );
      })}
    </div>
  );
}

function Cta({ cue, dur }: { cue: ProCue; dur: number }) {
  const p = useIn();
  const out = useOut(dur);
  const frame = useCurrentFrame();
  return (
    <div style={{ position: 'absolute', left: 70, right: 70, top: 260, borderRadius: 32, padding: '34px 40px', display: 'flex', alignItems: 'center', gap: 28, background: ACCENT, boxShadow: '0 40px 90px -20px rgba(255,106,43,.55)', opacity: out, transform: `translateX(${interpolate(p, [0, 1], [-1000, 0])}px)` }}>
      <span style={{ fontFamily: F.display, fontWeight: 800, fontSize: Math.min(64, fitText({ text: cue.text.toUpperCase(), withinWidth: 1500, fontFamily: F.display, fontWeight: 800, validateFontIsLoaded: false }).fontSize), color: '#111', textTransform: 'uppercase', lineHeight: 1.05, flex: 1 }}>{cue.text}</span>
      <span style={{ display: 'grid', placeItems: 'center', transform: `translateX(${Math.sin(frame / 5) * 8}px)` }}><ArrowRight size={96} color="#111" strokeWidth={3} /></span>
    </div>
  );
}

/** A real thing the speaker names: its icon pops in a glass disc beside them (upper right), labeled with their word. */
function IconPop({ cue, dur }: { cue: ProCue; dur: number }) {
  const frame = useCurrentFrame();
  const p = useIn();
  const out = useOut(dur);
  const I = cue.icon ? (icons as Record<string, React.ComponentType<{ size?: number; color?: string; strokeWidth?: number }>>)[cue.icon] : null;
  if (!I) return null;
  const bob = Math.sin(frame / 7) * 6;
  return (
    <div style={{ position: 'absolute', right: 90, top: 260, display: 'grid', justifyItems: 'center', gap: 16, opacity: out, transform: `translateY(${bob}px) scale(${interpolate(p, [0, 1], [0.2, 1])}) rotate(${interpolate(p, [0, 1], [-35, 0])}deg)` }}>
      <div style={{ width: 230, height: 230, borderRadius: '50%', display: 'grid', placeItems: 'center', ...GLASS, boxShadow: `0 30px 70px -20px rgba(0,0,0,.6), 0 0 0 6px ${ACCENT}` }}>
        <I size={130} color="#fff" strokeWidth={1.8} />
      </div>
      <span style={{ fontFamily: SERIF, fontStyle: 'italic', fontSize: 64, color: ACCENT, textShadow: '0 6px 24px rgba(0,0,0,.6)' }}>{cue.text}</span>
    </div>
  );
}

/** One cue's graphic, from its first frame (the Sequence starts on the word). */
export function CueGraphic({ cue, dur }: { cue: ProCue; dur: number }) {
  switch (cue.kind) {
    case 'counter': return <Counter cue={cue} dur={dur} />;
    case 'logo': return <Logo cue={cue} dur={dur} />;
    case 'list': return <List cue={cue} dur={dur} t0={cue.t} />;
    case 'question': return <Question cue={cue} dur={dur} />;
    case 'tap': return <Tap cue={cue} dur={dur} />;
    case 'headline': return <Headline cue={cue} dur={dur} />;
    case 'cta': return <Cta cue={cue} dur={dur} />;
    case 'icon': return <IconPop cue={cue} dur={dur} />;
    default: return null; // whip is a camera move only
  }
}

/** Real motion blur only while a graphic flies in or out (its first 12 and last 8 frames): where the eye sees
 *  speed. Holding frames render once, so the blur costs little. */
export function MovingBlur({ dur, children }: { dur: number; children: React.ReactNode }) {
  const frame = useCurrentFrame();
  return frame < 12 || frame >= dur - 8 ? <CameraMotionBlur shutterAngle={180} samples={5}>{children}</CameraMotionBlur> : <>{children}</>;
}

export function CueLayer({ cues, fps }: { cues: ProCue[]; fps: number }) {
  return (
    <AbsoluteFill style={{ pointerEvents: 'none' }}>
      {cues.map((c, i) => {
        const from = Math.max(0, Math.round(c.t * fps));
        const dur = Math.max(18, Math.round((c.end - c.t) * fps));
        return <Sequence key={i} from={from} durationInFrames={dur} name={`cue ${c.kind}`}><MovingBlur dur={dur}><CueGraphic cue={c} dur={dur} /></MovingBlur></Sequence>;
      })}
      {/* A warm light leak washes over a brand reveal and a call to action. */}
      {cues.filter((c) => c.kind === 'logo' || c.kind === 'cta').map((c, i) => (
        <LightLeak key={`leak${i}`} from={Math.max(0, Math.round(c.t * fps) - 4)} durationInFrames={Math.round(fps * 0.7)} seed={i + 3} hueShift={0} style={{ opacity: 0.32, mixBlendMode: 'screen' }} />
      ))}
    </AbsoluteFill>
  );
}

/** Light leaks on a cut into or out of a screen: the change reads as a designed transition. */
export function CutLeaks({ cuts, fps }: { cuts: number[]; fps: number }) {
  return <>{cuts.map((t, i) => <LightLeak key={i} from={Math.max(0, Math.round(t * fps) - 6)} durationInFrames={Math.round(fps * 0.6)} seed={i * 7 + 1} hueShift={0} style={{ opacity: 0.28, mixBlendMode: 'screen' }} />)}</>;
}

/** The camera: every cue's move applied to whatever is under it (the shot layer), on the cue's word. */
export function CameraRig({ cues, children }: { cues: ProCue[]; children: React.ReactNode }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  let scale = 1, x = 0, y = 0, blur = 0;
  for (const c of cues) {
    if (!c.cam) continue;
    const f0 = Math.round(c.t * fps), f1 = Math.round(c.end * fps);
    if (frame < f0 || frame > f1 + 10) continue;
    const k = frame - f0;
    const hold = interpolate(frame, [f1, f1 + 10], [1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
    if (c.cam === 'punch') scale *= 1 + 0.12 * spring({ frame: k, fps, config: { damping: 18, stiffness: 260 } }) * hold;
    if (c.cam === 'push') scale *= 1 + 0.06 * interpolate(frame, [f0, f1], [0, 1], { extrapolateRight: 'clamp' }) * hold;
    if (c.cam === 'pull') scale *= 1 + 0.06 * (1 - interpolate(frame, [f0, f1], [0, 1], { extrapolateRight: 'clamp' }));
    if (c.cam === 'shake' && k < 12) { const d = Math.exp(-k / 4); x += Math.sin(k * 2.7) * 14 * d; y += Math.cos(k * 3.3) * 10 * d; }
    if (c.cam === 'whip' && k < 9) { const w = Math.sin((k / 9) * Math.PI); x += (k < 5 ? -1 : 1) * 260 * w; blur += 26 * w; }
  }
  return (
    <AbsoluteFill style={{ transform: `translate(${x}px, ${y}px) scale(${scale})`, filter: blur > 0.5 ? `blur(${blur.toFixed(1)}px)` : undefined }}>
      {children}
    </AbsoluteFill>
  );
}

/** Each cue's sound from its slot (licensed sounds replace the files in public-pro/sfx; the names stay). */
export function CueSounds({ cues, fps }: { cues: ProCue[]; fps: number }) {
  const VOL: Record<string, number> = { hit: 0.42, whoosh: 0.4, riser: 0.36, pop: 0.32, click: 0.4, tick: 0.3, swish: 0.4, sting: 0.34 };
  return <>{cues.filter((c) => c.sound).map((c, i) => (
    <Sequence key={i} from={Math.max(0, Math.round((c.t - (c.sound === 'riser' ? 0.9 : c.sound === 'whoosh' ? 0.25 : 0)) * fps))} durationInFrames={Math.round(1.6 * fps)} name={`cue sound ${c.sound}`}>
      <Audio src={staticFile(`sfx/${c.sound}.wav`)} volume={VOL[c.sound!] ?? 0.35} />
    </Sequence>
  ))}</>;
}
