import React from 'react';
import { Composition } from 'remotion';
import { calculateProMetadata, UneditPro, type UneditProProps } from '../UneditPro';
import { calculateEpisodeCuesMetadata, UneditEpisodeCues, type EpisodeCuesProps } from '../UneditEpisodeCues';

const emptyEp: EpisodeCuesProps = { width: 2560, height: 1440, items: [] };

const empty: UneditProProps = { src: '', secs: 1, words: [], shots: [{ s: 0, e: 1, layout: 'face' }] };

export const ProRoot: React.FC = () => (
  <>
    <Composition id="UneditPro" component={UneditPro} calculateMetadata={calculateProMetadata} durationInFrames={30} fps={30} width={1080} height={1920} defaultProps={empty} />
    <Composition id="UneditEpisodeCues" component={UneditEpisodeCues} calculateMetadata={calculateEpisodeCuesMetadata} durationInFrames={30} fps={30} width={2560} height={1440} defaultProps={emptyEp} />
  </>
);
