// Ported from HyperFrames' extruded-logo block (Apache-2.0, see NOTICE): beveled 3D letters flip up one by one on
// their baseline, the word swings so the studio light runs across the bevels, then it settles facing camera.
// Genovus version: chrome GEN and VUS with a glossy 3D egg standing in for the O. Transparent background, so it
// renders into the graphics reel over footage. Deterministic: every frame is render(t).
import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { AbsoluteFill, continueRender, delayRender, staticFile } from 'remotion';
import * as THREE from 'three';
import { FontLoader } from 'three/examples/jsm/loaders/FontLoader.js';
import { TextGeometry } from 'three/examples/jsm/geometries/TextGeometry.js';
import { E, tw, useT } from './ease';
import { HF, Scrim } from './blocks';

type Scene = { render: (t: number) => void; dispose: () => void };

async function build(canvas: HTMLCanvasElement, w: number, h: number, dur: number, finish: 'chrome' | 'gold'): Promise<Scene> {
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, preserveDrawingBuffer: true });
  renderer.setPixelRatio(1);
  renderer.setSize(w, h, false);
  renderer.setClearColor(0x000000, 0);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;

  const scene = new THREE.Scene();
  // Softbox studio: bright strips on black, so chrome shows crisp bands instead of grey.
  const studio = new THREE.Scene();
  studio.background = new THREE.Color(0x040406);
  const softbox = (sw: number, sh: number, x: number, y: number, z: number, color: THREE.ColorRepresentation, power: number) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(sw, sh), new THREE.MeshBasicMaterial({ color: new THREE.Color(color).multiplyScalar(power), side: THREE.DoubleSide }));
    m.position.set(x, y, z); m.lookAt(0, 0, 0); studio.add(m);
  };
  softbox(10, 2.2, 0, 7, 1, 0xffffff, 3);
  softbox(1.2, 7, -7, 1, 2, 0xffffff, 2.2);
  softbox(1.2, 7, 7, 1, -1, 0xffffff, 1.6);
  const bars = document.createElement('canvas'); bars.width = 1024; bars.height = 256;
  const bg = bars.getContext('2d')!;
  const fade = bg.createLinearGradient(0, 0, 0, 256); fade.addColorStop(0, '#9a9ca3'); fade.addColorStop(1, '#15161a');
  bg.fillStyle = fade; bg.fillRect(0, 0, 1024, 256); bg.fillStyle = '#ffffff';
  for (const [x, bw] of [[150, 60], [430, 140], [760, 36]]) bg.fillRect(x, 0, bw, 256);
  const mirror = new THREE.Mesh(new THREE.PlaneGeometry(22, 8), new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(bars), color: new THREE.Color(2.2, 2.2, 2.2), side: THREE.DoubleSide }));
  mirror.position.set(0, 1, 9); mirror.lookAt(0, 1, 0); studio.add(mirror);
  softbox(9, 1.4, 0, 0.5, -7, '#ffe2c4', 2); // warm rim, toward the brand orange
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(studio, 0.01).texture;

  const camera = new THREE.PerspectiveCamera(26, w / h, 0.1, 100);
  camera.position.set(0, 0.9, 11); camera.lookAt(0, 0.35, 0);
  const rim = new THREE.DirectionalLight(new THREE.Color('#ffe2c4'), 5); rim.position.set(0, 3, -6); scene.add(rim);
  const key = new THREE.DirectionalLight(0xffffff, 1.4); key.position.set(-5, 4, 6); scene.add(key);

  const finishes = { chrome: { color: 0xe9ecf2, metalness: 1, roughness: 0.16 }, gold: { color: 0xe7bf6a, metalness: 1, roughness: 0.2 } };
  const material = new THREE.MeshStandardMaterial(finishes[finish]);
  const eggMat = new THREE.MeshPhysicalMaterial({ color: new THREE.Color('#ff7414'), metalness: 0.05, roughness: 0.22, clearcoat: 1, clearcoatRoughness: 0.04, sheen: 0.3, sheenColor: new THREE.Color('#ffc878') });

  const json = await fetch(staticFile('fonts/Geist-Bold.typeface.json')).then((r) => r.json());
  const font = new FontLoader().parse(json);
  const SIZE = 1.5, scale = SIZE / font.data.resolution, tracking = 0.08;
  const word = new THREE.Group(); scene.add(word);
  const letters: THREE.Group[] = [];
  let cursor = 0;
  const glyphs = font.data.glyphs as Record<string, { ha?: number }>;
  for (const ch of ['G', 'E', 'N', 'egg', 'V', 'U', 'S']) {
    const pivot = new THREE.Group();
    let advance: number;
    if (ch === 'egg') {
      // The egg: a lathe of an egg profile (narrow top), .677 x .867 of the type size like the 2D wordmark, tipped -8°.
      const pts: THREE.Vector2[] = [];
      for (let i = 0; i <= 48; i++) {
        const y = -1 + (2 * i) / 48;
        pts.push(new THREE.Vector2(Math.sqrt(Math.max(0, 1 - y * y)) * (1 - 0.16 * y) * 0.5, y * 0.65));
      }
      const g = new THREE.LatheGeometry(pts, 96);
      const egg = new THREE.Mesh(g, eggMat);
      egg.scale.setScalar(SIZE * 0.82);
      egg.position.y = SIZE * 0.53;
      egg.rotation.z = 0.14;
      pivot.add(egg);
      advance = SIZE * 0.72;
    } else {
      advance = ((glyphs[ch] || glyphs['?']).ha || 600) * scale;
      const geometry = new TextGeometry(ch, { font, size: SIZE, depth: 0.42, curveSegments: 10, bevelEnabled: true, bevelThickness: 0.06, bevelSize: 0.035, bevelSegments: 5 });
      geometry.computeBoundingBox();
      const b = geometry.boundingBox!;
      geometry.translate(-(b.min.x + b.max.x) / 2, 0, -0.21);
      pivot.add(new THREE.Mesh(geometry, material));
    }
    pivot.position.x = cursor + advance / 2;
    word.add(pivot); letters.push(pivot);
    cursor += advance + tracking;
  }
  const width = cursor - tracking;
  for (const p of letters) p.position.x -= width / 2;
  word.scale.setScalar(Math.min(1, 7.4 / width) * 0.84);

  // (The block's floor shadow is left out: over footage there is no floor, and its edge read as a line.)
  const c01 = (x: number) => Math.min(1, Math.max(0, x));
  const backOut = (x: number) => { const v = c01(x) - 1; return 1 + 2.2 * v * v * v + 1.2 * v * v; };
  const inOut = (x: number) => { const v = c01(x); return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2; };
  const render = (t: number) => {
    const k = Math.min(1, dur / 5);
    letters.forEach((p, i) => {
      const v = backOut((t - 0.1 * k - i * 0.13 * k) / (0.9 * k));
      p.rotation.x = (1 - v) * (-Math.PI / 2);
      p.position.y = (1 - c01(v)) * -0.2;
      p.visible = t >= 0.1 * k + i * 0.13 * k;
    });
    const swing = inOut((t - 0.9 * k) / (dur - 0.9 * k - 0.7 * k));
    word.rotation.y = -0.42 + swing * 0.42;
    word.rotation.x = 0.04 - swing * 0.04;
    renderer.render(scene, camera);
  };
  return { render, dispose: () => { renderer.dispose(); pmrem.dispose(); } };
}

export function ExtrudedMark({ dur, tagline, finish = 'chrome' }: { dur: number; tagline: string; finish?: 'chrome' | 'gold' }) {
  const { t, u, width, height } = useT();
  const ref = useRef<HTMLCanvasElement>(null);
  const scene = useRef<Scene | null>(null);
  const [ready] = useState(() => delayRender('extruded mark'));
  useEffect(() => {
    let live = true;
    build(ref.current!, width, height, dur, finish)
      .then((s) => { if (!live) return s.dispose(); scene.current = s; s.render(t); continueRender(ready); })
      .catch((e) => { console.error(e); continueRender(ready); });
    return () => { live = false; scene.current?.dispose(); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useLayoutEffect(() => { scene.current?.render(t); }, [t]);
  const tag = tw(t, Math.min(1.7, dur * 0.34), 0.6, E.p2Out);
  const out = tw(t, dur - 0.45, 0.45, E.p2In);
  return (
    <AbsoluteFill style={{ opacity: 1 - out }}>
      <Scrim side="full" amount={0.88} opacity={tw(t, 0, 0.45, E.p2Out)} />
      <AbsoluteFill style={{ background: `radial-gradient(${900 * u}px ${560 * u}px at 50% 46%, rgba(255,255,255,0.07), transparent 70%)`, opacity: tw(t, 0, 0.45, E.p2Out) }} />
      <canvas ref={ref} width={width} height={height} style={{ position: 'absolute', inset: 0, width, height }} />
      <div style={{ position: 'absolute', left: 0, right: 0, top: 790 * u, textAlign: 'center', fontFamily: HF.geist, fontWeight: 500, fontSize: 38 * u, letterSpacing: '0.02em', color: 'rgba(236,238,245,0.78)', opacity: tag, transform: `translateY(${(1 - tag) * 16 * u}px)` }}>{tagline}</div>
    </AbsoluteFill>
  );
}
