// Ported from HeyGen HyperFrames (Apache-2.0, https://github.com/heygen-com/hyperframes, see NOTICE): the blocks'
// timings, eases and type treatments, rebuilt as Remotion components on the frame clock. Every size scales off
// `u` (1 at 1920 px wide), so the same block renders at 2560x1440 episodes and 1080x1920 clips.
import React from 'react';
import { AbsoluteFill, continueRender, delayRender, Img, staticFile } from 'remotion';
import { measureText } from '@remotion/layout-utils';
import { E, mix, tw, useT } from './ease';

export const HF = {
  geist: 'Geist, Inter, "Segoe UI", sans-serif',
  inter: 'Inter, "Segoe UI", sans-serif',
  mono: '"JetBrains Mono", Consolas, monospace',
  serif: '"Instrument Serif", Georgia, serif',
  wide: '"Archivo Expanded", "Arial Black", sans-serif',
  orange: '#FF8A1E',
  deep: '#F45A1B',
  cream: '#F7F3EC',
};

const FACES: [string, string, string, string?][] = [
  ['Geist', 'geist-latin-500.woff2', '500'],
  ['Geist', 'geist-latin-600.woff2', '600'],
  ['Geist', 'geist-latin-700.woff2', '700'],
  ['Geist', 'geist-latin-800.woff2', '800'],
  ['Inter', 'inter-latin-500-normal.woff2', '500'],
  ['Inter', 'inter-latin-600-normal.woff2', '600'],
  ['Inter', 'inter-latin-700-normal.woff2', '700'],
  ['Inter', 'inter-latin-800-normal.woff2', '800'],
  ['JetBrains Mono', 'jetbrains-mono-latin-500.woff2', '500'],
  ['Archivo Expanded', 'archivo-expanded-latin-800.woff2', '800'],
  ['Instrument Serif', 'instrument-serif-italic.ttf', '400', 'italic'],
];
if (typeof document !== 'undefined') {
  const h = delayRender('hf fonts');
  Promise.all(FACES.map(([family, file, weight, style]) => new FontFace(family, `url(${staticFile(`fonts/${file}`)})`, { weight, style: style ?? 'normal' }).load().then((f) => document.fonts.add(f))))
    .then(() => continueRender(h))
    .catch((e) => { console.error(e); continueRender(h); });
}

/** A soft dark falloff behind type, so it reads over any footage (fades with the block). */
export function Scrim({ side, amount, opacity }: { side: 'left' | 'bottom' | 'full'; amount?: number; opacity: number }) {
  const a = amount ?? 0.62;
  const bg = side === 'left'
    ? `linear-gradient(90deg, rgba(6,7,10,${a}) 0%, rgba(6,7,10,${a * 0.55}) 32%, rgba(6,7,10,0) 62%)`
    : side === 'bottom'
      ? `linear-gradient(0deg, rgba(6,7,10,${a}) 0%, rgba(6,7,10,${a * 0.5}) 28%, rgba(6,7,10,0) 55%)`
      : `radial-gradient(120% 90% at 50% 50%, rgba(6,7,10,${a * 0.7}) 0%, rgba(6,7,10,${a}) 100%)`;
  return <AbsoluteFill style={{ background: bg, opacity }} />;
}

// ---- titlecard-calm: mono kicker, generous grotesque headline fading upward, an almost imperceptible drift --------
export function TitleCalm({ kicker, headline, dur, scrim = true, maxW }: { kicker: string; headline: string; dur: number; scrim?: boolean; /** widest it may run, as a fraction of the frame (stops short of the speaker) */ maxW?: number }) {
  const { t, u, width: fw, height } = useT();
  const boxW = Math.min(980 * u, maxW ? maxW * fw : Infinity);
  const type = Math.max(0.72, Math.min(1, boxW / (980 * u))); // a narrower block sets slightly smaller type
  const IN = 1.2, OUT = 0.55, HOLD = Math.max(0, dur - IN - OUT);
  const ch = height / 100; // 1cqh
  const k = tw(t, 0, 0.5, E.p2Out);
  const h = tw(t, 0.28, 0.72, E.p3Out);
  const drift = HOLD > 0 ? tw(t, IN, HOLD, E.sineInOut) * -0.65 * ch : 0;
  const out = tw(t, IN + HOLD, OUT, E.p2In);
  const lockY = drift + out * -2.1 * ch;
  const fade = 1 - out;
  return (
    <AbsoluteFill>
      {scrim ? <Scrim side="left" opacity={Math.min(k, fade)} /> : null}
      <div style={{ position: 'absolute', left: 150 * u, bottom: 190 * u, width: boxW, transform: `translateY(${lockY}px)`, opacity: fade }}>
        <div style={{ fontFamily: HF.mono, fontWeight: 500, fontSize: 26 * u, letterSpacing: '0.18em', color: 'rgba(235,238,245,0.78)', textTransform: 'uppercase', opacity: k, transform: `translateY(${(1 - k) * 2.2 * ch}px)`, marginBottom: 26 * u, display: 'flex', alignItems: 'center', gap: 16 * u }}>
          <span style={{ width: 36 * u, height: 3 * u, background: HF.orange, display: 'inline-block' }} />
          {kicker}
        </div>
        <div style={{ fontFamily: HF.geist, fontWeight: 600, fontSize: 112 * u * type, lineHeight: 0.94, letterSpacing: '-0.045em', color: HF.cream, textWrap: 'balance', opacity: h, transform: `translateY(${(1 - h) * 3.2 * ch}px)`, textShadow: `0 ${2 * u}px ${30 * u}px rgba(0,0,0,.35)` }}>
          {headline}
        </div>
      </div>
    </AbsoluteFill>
  );
}

// ---- lt-mask-reveal: an accent sweep crosses and clip-path-reveals a heavy name; role fades up --------------------
export function LowerMaskReveal({ name, role, dur = 4.8, egg = false }: { name: string; role: string; dur?: number; egg?: boolean }) {
  const { t, u } = useT();
  const s = dur / 4.8 > 1 ? 1 : dur / 4.8;
  const end = dur - 4.8 * s;
  const sweepOn = tw(t, 0.1, 0.12) * (1 - tw(t, 0.6, 0.15));
  const sweepX = tw(t, 0.12, 0.55, E.p2InOut);
  const reveal = tw(t, 0.16, 0.5, E.p2InOut);
  const roleIn = tw(t, 0.55, 0.5, E.p3Out);
  const roleOut = tw(t, end + 4.25 * s, 0.3, E.p2In);
  const unwipe = tw(t, end + 4.3 * s, 0.4, E.p2In);
  if (t > dur - 0.05) return null;
  return (
    <AbsoluteFill>
      <div style={{ position: 'absolute', left: 130 * u, bottom: 122 * u, display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: 14 * u }}>
        <div style={{ position: 'relative', overflow: 'hidden', padding: `${2 * u}px 0`, display: 'flex', alignItems: 'center', gap: 18 * u }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 20 * u, clipPath: `inset(0 ${(1 - reveal) * 100}% 0 ${unwipe * 100}%)` }}>
            {egg ? <Img src={staticFile('brand/genovus-egg.svg')} style={{ width: 52 * u, height: 66 * u, transform: 'rotate(-8deg)' }} /> : null}
            <div style={{ fontFamily: HF.geist, fontSize: 72 * u, fontWeight: 800, color: '#fff', lineHeight: 0.98, letterSpacing: '-0.02em', whiteSpace: 'nowrap', textShadow: `0 ${2 * u}px ${22 * u}px rgba(0,0,0,.45)` }}>{name}</div>
          </div>
          <div style={{ position: 'absolute', top: 0, bottom: 0, left: `${sweepX * 100}%`, width: 8 * u, background: HF.orange, opacity: sweepOn, boxShadow: `0 0 ${24 * u}px ${HF.orange}` }} />
        </div>
        <div style={{ fontFamily: HF.mono, fontSize: 28 * u, fontWeight: 500, color: '#e7eaf0', letterSpacing: '0.02em', whiteSpace: 'nowrap', textShadow: `0 ${2 * u}px ${16 * u}px rgba(0,0,0,.45)`, opacity: roleIn * (1 - roleOut), transform: `translateY(${(1 - roleIn) * 14 * u}px)` }}>{role}</div>
      </div>
    </AbsoluteFill>
  );
}

// ---- lt-accent-underline: name rises, an accent rule draws left to right, role fades up under it ------------------
export function LowerAccentUnderline({ name, role, dur = 4.8, font = HF.geist, upper = true }: { name: string; role: string; dur?: number; font?: string; upper?: boolean }) {
  const { t, u } = useT();
  const end = dur - 4.8;
  const n = tw(t, 0.1, 0.55, E.p3Out), r = tw(t, 0.3, 0.5, E.p4Out), ro = tw(t, 0.46, 0.5, E.p3Out);
  const roOut = tw(t, end + 4.25, 0.3, E.p2In), rOut = tw(t, end + 4.3, 0.3, E.p2In), nOut = tw(t, end + 4.35, 0.32, E.p2In);
  if (t > dur - 0.05) return null;
  return (
    <AbsoluteFill>
      <div style={{ position: 'absolute', left: 130 * u, bottom: 120 * u, display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: 14 * u }}>
        <div style={{ fontFamily: font, fontSize: 76 * u, fontWeight: 700, color: '#fff', lineHeight: 0.96, letterSpacing: upper ? '0.005em' : '-0.02em', textTransform: upper ? 'uppercase' : 'none', whiteSpace: 'nowrap', textShadow: `0 ${2 * u}px ${22 * u}px rgba(0,0,0,.45)`, opacity: n * (1 - nOut), transform: `translateY(${(1 - n) * 28 * u - nOut * 16 * u}px)` }}>{name}</div>
        <div style={{ height: 6 * u, width: '100%', background: HF.orange, borderRadius: 3 * u, transformOrigin: '0% 50%', transform: `scaleX(${r * (1 - rOut)})` }} />
        <div style={{ fontFamily: HF.mono, fontSize: 28 * u, fontWeight: 500, color: '#e7eaf0', lineHeight: 1.2, letterSpacing: '0.04em', whiteSpace: 'nowrap', textShadow: `0 ${2 * u}px ${16 * u}px rgba(0,0,0,.45)`, opacity: ro * (1 - roOut), transform: `translateY(${(1 - ro) * 16 * u}px)` }}>{role}</div>
      </div>
    </AbsoluteFill>
  );
}

// ---- yt-prism-title: focus in from heavy blur, red/blue prism copies settle from wide, slow breath, blur out -------
export function PrismTitle({ title, kicker, dur, size = 200, color = HF.cream, font = HF.geist, weight = 700, italic = false, y = 0.5, bow = 6 }: { title: string; kicker?: string; dur: number; size?: number; color?: string; font?: string; weight?: number; italic?: boolean; y?: number; bow?: number }) {
  const { t, u, width, height } = useT();
  // Fit: the title never runs past 84 % of the frame width.
  const natural = measureText({ text: title, fontFamily: font, fontSize: size * u, fontWeight: weight, validateFontIsLoaded: false }).width;
  const fs = natural > width * 0.84 ? (size * u * width * 0.84) / natural : size * u;
  const IN = Math.min(0.8, Math.max(0.3, dur * 0.08)), OUT = Math.min(0.6, Math.max(0.25, dur * 0.06)), O = 4 * u;
  const op = tw(t, 0.1, IN * 1.4, E.p2Out);
  const focus = tw(t, 0.1, IN * 2.4, E.p2Out);
  const out = tw(t, dur - OUT - 0.05, OUT, E.p2In);
  const blur = mix(18, 2.5 * 0.6, focus) * u + out * 12 * u;
  const spread = mix(O * 4.5, O, focus);
  const popA = mix(0.45, 0.85, focus);
  const wob = t > 1.4 ? Math.sin(((t - 1.4) / 1.9) * Math.PI) * 1.4 * u : 0;
  const breathe = 1 + 0.035 * tw(t, 0.4, dur - 1, E.sineOut);
  if (t > dur - 0.02) return null;
  const line = (c: string, dx: number, a: number) => (
    <div style={{ position: 'absolute', inset: 0, color: c, opacity: a, transform: `translateX(${dx}px)` }}>{title}</div>
  );
  return (
    <AbsoluteFill style={{ alignItems: 'center', justifyContent: 'center', perspective: 950 * u }}>
      <div style={{ position: 'absolute', top: height * y, left: 0, right: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', transform: `translateY(-50%) rotateX(${bow}deg)`, opacity: op * (1 - out), filter: `blur(${blur}px)` }}>
        {kicker ? <div style={{ fontFamily: HF.mono, fontWeight: 500, fontSize: 28 * u, letterSpacing: '0.32em', color: HF.orange, marginBottom: 22 * u }}>{kicker}</div> : null}
        <div style={{ position: 'relative', fontFamily: font, fontStyle: italic ? 'italic' : 'normal', fontWeight: weight, fontSize: fs, lineHeight: 1, letterSpacing: italic ? '-0.01em' : '-0.03em', whiteSpace: 'nowrap', transform: `scale(${breathe})` }}>
          {line('#ff2a4d', -spread - wob, popA)}
          {line('#2a7fff', spread + wob, popA)}
          <div style={{ position: 'relative', color }}>{title}</div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

// ---- mk-emphasis-type: an oversized word drifting slowly, typography as texture (sits behind the subject) ---------
export function EmphasisWord({ text, dur, top, left = -40, drift = -110, size = 300, color = 'rgba(247,243,236,0.92)', font = HF.geist, weight = 800, italic = false, upper = true }: { text: string; dur: number; top: number; left?: number; drift?: number; size?: number; color?: string; font?: string; weight?: number; italic?: boolean; upper?: boolean }) {
  const { t, u } = useT();
  const inn = tw(t, 0, 1.0, E.p2Out);
  const x = mix(40, 40 + drift, tw(t, 0, dur, E.sineInOut));
  const out = tw(t, dur - 0.5, 0.5, E.p2In);
  return (
    <AbsoluteFill>
      <div style={{ position: 'absolute', top: top * u, left: left * u, fontFamily: font, fontStyle: italic ? 'italic' : 'normal', fontWeight: weight, fontSize: size * u, lineHeight: 0.86, letterSpacing: italic ? '-0.02em' : '-0.04em', textTransform: upper ? 'uppercase' : 'none', whiteSpace: 'nowrap', color, opacity: inn * (1 - out), transform: `translateX(${x * u}px)` }}>{text}</div>
    </AbsoluteFill>
  );
}

// ---- kinetic-center-build (Remocn, MIT, via HyperFrames): words enter from the right and push the phrase left,
// each intermediate phrase centered, until the final line locks ----------------------------------------------------
export function KineticCenterBuild({ text, dur, size = 120, color = '#fff', accent, font = HF.geist, weight = 700, y = 0.5 }: { text: string; dur: number; size?: number; color?: string; accent?: number; font?: string; weight?: number; y?: number }) {
  const { t, u, width, height } = useT();
  const words = text.split(/\s+/);
  let fs = size * u;
  const widthsAt = (s: number) => words.map((w) => measureText({ text: w, fontFamily: font, fontSize: s, fontWeight: weight, letterSpacing: '-0.03em', validateFontIsLoaded: false }).width);
  let ws = widthsAt(fs);
  let gap = fs * (10 / 72);
  const full = ws.reduce((a, b) => a + b, 0) + gap * (words.length - 1);
  if (full > width * 0.86) { fs *= (width * 0.86) / full; ws = widthsAt(fs); gap = fs * (10 / 72); }
  const pos: number[][] = [];
  for (let c = 1; c <= words.length; c++) {
    let total = gap * (c - 1); for (let i = 0; i < c; i++) total += ws[i];
    let cur = -total / 2; const p: number[] = [];
    for (let i = 0; i < c; i++) { p.push(cur + ws[i] / 2); cur += ws[i] + gap; }
    pos.push(p);
  }
  const ease = E.bezier(0.2, 0.8, 0.2, 1);
  let first = 10 / 30, push = 13 / 30;
  const scale = Math.min(1, Math.max(0.25, dur - 0.5) / (first + Math.max(0, words.length - 1) * push));
  first *= scale; push *= scale;
  const startOf = (i: number) => (i === 0 ? 0 : first + (i - 1) * push);
  const out = tw(t, dur - 0.4, 0.4, E.p2In);
  return (
    <AbsoluteFill>
      {words.map((w, i) => {
        const st = startOf(i), md = i === 0 ? first : push;
        const p = tw(t, st, md, ease);
        if (t < st) return null;
        // x: its own entry, then each later word's push.
        let x = i === 0 ? pos[0][0] : mix(pos[i][i] + 88 * u, pos[i][i], p);
        for (let j = i + 1; j < words.length; j++) {
          const sj = startOf(j);
          if (t >= sj) x = mix(pos[j - 1][i], pos[j][i], tw(t, sj, push, ease));
        }
        let blur = mix(3.5, 0, p);
        for (let j = i + 1; j < words.length; j++) {
          const sj = startOf(j), q = (t - sj) / push;
          if (q > 0 && q < 1) blur = Math.max(blur, 0.8 * (1 - Math.abs(q * 2 - 1)));
        }
        return (
          <div key={i} style={{ position: 'absolute', left: width / 2, top: height * y, fontFamily: font, fontWeight: weight, fontSize: fs, lineHeight: 1, letterSpacing: '-0.03em', whiteSpace: 'nowrap', color: i === accent ? HF.orange : color, opacity: p * (1 - out), filter: `blur(${blur * u}px)`, transform: `translate(-50%, -50%) translate(${x}px, ${(i === 0 ? (1 - p) * 6 : 0) * u - out * 20 * u}px) scale(${mix(0.992, 1, p)})`, textShadow: `0 ${4 * u}px ${30 * u}px rgba(0,0,0,.45)` }}>{w}</div>
        );
      })}
    </AbsoluteFill>
  );
}

// ---- logo-brand-close: wordmark letters cascade in on a long expo tail while the lockup settles from 104 %, the
// accent period pops last, tagline and URL follow, then a still hold. Genovus: the egg stands in for the O. --------
export function BrandClose({ tagline, url, dur, bg = true }: { tagline: string; url: string; dur: number; bg?: boolean }) {
  const { t, u } = useT();
  const IN = 2.6, OUT = 0.5;
  const sc = dur < IN + OUT ? dur / (IN + OUT) : 1;
  const chars = ['G', 'E', 'N', 'egg', 'V', 'U', 'S'];
  const stagger = (0.7 * sc) / (chars.length - 1);
  const settle = mix(1.04, 1, tw(t, 0, 2.4 * sc, E.expoOut));
  const per = tw(t, 0.95 * sc, 0.9 * sc, E.backOut(1.8));
  const tag = tw(t, 1.35 * sc, 0.9 * sc, E.p3Out);
  const link = tw(t, 1.7 * sc, 0.85 * sc, E.p2Out);
  const out = tw(t, dur - OUT * sc, OUT * sc, E.p2In);
  const size = 190 * u;
  return (
    <AbsoluteFill style={{ alignItems: 'center', justifyContent: 'center', opacity: 1 - out }}>
      {bg ? <Scrim side="full" amount={0.86} opacity={tw(t, 0, 0.5, E.p2Out)} /> : null}
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', transform: `scale(${settle})`, transformOrigin: '50% 100%' }}>
        <div style={{ display: 'flex', alignItems: 'flex-end', fontFamily: HF.wide, fontWeight: 800, fontSize: size, lineHeight: 1, letterSpacing: '-0.01em', color: '#fff' }}>
          {chars.map((c, i) => {
            const p = tw(t, i * stagger, 1.15 * sc, E.expoOut);
            const style: React.CSSProperties = { display: 'inline-block', opacity: p, transform: `translateY(${(1 - p) * 0.62}em)` };
            return c === 'egg'
              ? <Img key={i} src={staticFile('brand/genovus-egg.svg')} style={{ ...style, width: '0.677em', height: '0.867em', margin: '0 -0.05em 0.04em', transform: `${style.transform} rotate(-8deg)`, filter: `drop-shadow(0 0 ${0.14 * size}px rgba(244,90,27,.35))` }} />
              : <span key={i} style={style}>{c}</span>;
          })}
          <span style={{ display: 'inline-block', color: HF.orange, opacity: per, transform: `translateY(${(1 - per) * 0.08}em) scale(${mix(0.2, 1, per)})`, transformOrigin: '50% 65%' }}>.</span>
        </div>
        <div style={{ marginTop: 34 * u, fontFamily: HF.geist, fontWeight: 500, fontSize: 46 * u, letterSpacing: '0.01em', color: '#f8fafc', opacity: tag, transform: `translateY(${(1 - tag) * 0.9}em)` }}>{tagline}</div>
        <div style={{ marginTop: 22 * u, fontFamily: HF.mono, fontWeight: 500, fontSize: 30 * u, letterSpacing: '0.28em', color: '#94a3b8', textTransform: 'uppercase', opacity: link, transform: `scaleX(${mix(1.06, 1, link)})` }}>{url}</div>
      </div>
    </AbsoluteFill>
  );
}
