// The episode's graphics reel: everything Unedit draws over a long-form episode, rendered once as ONE transparent
// video (VP8 with alpha) with every item back to back. Unedit's part workers lay each item's stretch of the reel over
// the episode at its own moment (gss-unedit lib/unedit-episode.ts), so a long episode keeps rendering in parallel.
//   title     the episode's title, kinetic, lower left, over the first seconds
//   lower     the Genovus lower-third (egg, wordmark, a line under it)
//   chapter   a chapter card at each chapter's start (number, title, a marker stroke drawing under it)
//   end       the end card: the call to action and genovus.io
//   cue       any clip cue (counter, logo, list, question, tap, headline, cta, icon), drawn on a 9:16 stage that sits
//             on the right of a landscape frame (or fills a portrait one), so the speaker keeps the center
import React from 'react';
import { AbsoluteFill, Img, interpolate, Sequence, spring, staticFile, useCurrentFrame, useVideoConfig, type CalculateMetadataFunction } from 'remotion';
import { LightLeak } from '@remotion/light-leaks';
import { fitText } from '@remotion/layout-utils';
import { F } from './brand';
import { ACCENT, CueGraphic, GLASS, GOLD, Marker, MovingBlur, SERIF, type ProCue } from './UneditCues';
import { BrandClose, EmphasisWord, HF, KineticCenterBuild, LowerAccentUnderline, LowerMaskReveal, PrismTitle, Scrim, TitleCalm } from './hf/blocks';
import { ExtrudedMark } from './hf/ExtrudedMark';
import { E, tw, useT } from './hf/ease';

export type EpItem = { at: number; dur: number; kind: 'title' | 'lower' | 'chapter' | 'end' | 'cue' | 'kinetic' | 'emphasis'; text: string; sub?: string; n?: number; cue?: ProCue;
  /** A style from the Unedit style book (gss-unedit data/unedit-stylebook.ts); none = the classic look below. */ style?: string; accent?: number; maxW?: number };
export type EpisodeCuesProps = { width: number; height: number; items: EpItem[] };
const FPS = 30;

export const calculateEpisodeCuesMetadata: CalculateMetadataFunction<EpisodeCuesProps> = ({ props }) => ({
  durationInFrames: Math.max(1, Math.round((Math.max(0, ...props.items.map((i) => i.at + i.dur)) + 0.2) * FPS)),
  fps: FPS, width: props.width, height: props.height,
});

function useIn(delay = 0) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  return spring({ frame: frame - delay, fps, config: { damping: 16, stiffness: 150, mass: 0.8 } });
}
function useOut(dur: number) {
  const frame = useCurrentFrame();
  return interpolate(frame, [dur - 10, dur], [1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
}

/** The episode title, kinetic: words rise into place over an orange rule, lower left. */
function Title({ item, dur, u }: { item: EpItem; dur: number; u: number }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const out = useOut(dur);
  const words = item.text.split(' ');
  const size = Math.min(110 * u, fitText({ text: item.text.toUpperCase(), withinWidth: 1500 * u, fontFamily: F.display, fontWeight: 800, validateFontIsLoaded: false }).fontSize);
  const rule = interpolate(frame, [2, 18], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  return (
    <AbsoluteFill style={{ opacity: out }}>
      <div style={{ position: 'absolute', left: 120 * u, bottom: 150 * u, right: 700 * u }}>
        <div style={{ width: `${rule * 220 * u}px`, height: 12 * u, background: ACCENT, borderRadius: 6 * u, marginBottom: 26 * u }} />
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: `0 ${22 * u}px` }}>
          {words.map((w, i) => {
            const q = spring({ frame: frame - 4 - i * 2, fps, config: { damping: 14, stiffness: 190 } });
            return <span key={i} style={{ fontFamily: F.display, fontWeight: 800, fontSize: size, lineHeight: 1.04, color: '#fff', textTransform: 'uppercase', opacity: q, transform: `translateY(${interpolate(q, [0, 1], [50 * u, 0])}px)`, textShadow: '0 10px 50px rgba(0,0,0,.7)' }}>{w}</span>;
          })}
        </div>
        {item.sub ? <div style={{ marginTop: 18 * u, fontFamily: SERIF, fontStyle: 'italic', fontSize: 64 * u, color: GOLD, opacity: interpolate(frame, [14, 26], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }), textShadow: '0 6px 30px rgba(0,0,0,.7)' }}>{item.sub}</div> : null}
      </div>
      <LightLeak durationInFrames={Math.round(FPS * 1.1)} seed={5} hueShift={0} style={{ opacity: 0.3, mixBlendMode: 'screen' }} />
    </AbsoluteFill>
  );
}

/** The Genovus lower-third: a glass bar with the egg, the wordmark and one line, sliding in from the left. */
function Lower({ item, dur, u }: { item: EpItem; dur: number; u: number }) {
  const p = useIn();
  const out = useOut(dur);
  return (
    <div style={{ position: 'absolute', left: 110 * u, bottom: 120 * u, display: 'flex', alignItems: 'center', gap: 28 * u, padding: `${26 * u}px ${44 * u}px`, borderRadius: 30 * u, ...GLASS, background: 'rgba(14,16,22,.78)', opacity: out, transform: `translateX(${interpolate(p, [0, 1], [-900 * u, 0])}px)` }}>
      <Img src={staticFile('brand/genovus-egg.svg')} style={{ width: 62 * u, height: 78 * u }} />
      <div>
        <div style={{ fontFamily: F.display, fontWeight: 800, fontSize: 54 * u, letterSpacing: '0.06em', color: '#fff', lineHeight: 1 }}>{item.text.toUpperCase()}</div>
        {item.sub ? <div style={{ marginTop: 10 * u, fontFamily: F.body, fontWeight: 500, fontSize: 32 * u, color: '#D9D6CF' }}>{item.sub}</div> : null}
      </div>
    </div>
  );
}

/** A chapter card: "CHAPTER 02" small, the title large, a marker stroke drawing under it; left of the speaker. */
function Chapter({ item, dur, u }: { item: EpItem; dur: number; u: number }) {
  const p = useIn();
  const out = useOut(dur);
  const size = Math.min(92 * u, fitText({ text: item.text.toUpperCase(), withinWidth: 980 * u, fontFamily: F.display, fontWeight: 800, validateFontIsLoaded: false }).fontSize);
  return (
    <div style={{ position: 'absolute', left: 120 * u, top: 150 * u, maxWidth: 1050 * u, padding: `${34 * u}px ${46 * u}px ${30 * u}px`, borderRadius: 36 * u, ...GLASS, background: 'rgba(14,16,22,.74)', opacity: out, transform: `translateY(${interpolate(p, [0, 1], [-60 * u, 0])}px)` }}>
      <div style={{ fontFamily: F.mono, fontWeight: 500, fontSize: 30 * u, letterSpacing: '0.2em', color: GOLD }}>CHAPTER {String(item.n ?? 1).padStart(2, '0')}</div>
      <div style={{ marginTop: 10 * u, fontFamily: F.display, fontWeight: 800, fontSize: size, color: '#fff', textTransform: 'uppercase', lineHeight: 1.05 }}>{item.text}</div>
      <div style={{ marginTop: 6 * u, width: 520 * u }}><Marker width={Math.round(520 * u)} delay={10} /></div>
    </div>
  );
}

/** The end card: the call to action large and centered, genovus.io under it, a pulsing ring. */
function End({ item, dur, u }: { item: EpItem; dur: number; u: number }) {
  const frame = useCurrentFrame();
  const p = useIn();
  const out = useOut(dur + 20);
  const pulse = 1 + Math.sin(frame / 6) * 0.03;
  return (
    <AbsoluteFill style={{ opacity: out, background: `rgba(10,12,16,${interpolate(p, [0, 1], [0, 0.55])})` }}>
      <div style={{ position: 'absolute', left: 0, right: 0, top: '30%', display: 'grid', justifyItems: 'center', gap: 30 * u, transform: `scale(${interpolate(p, [0, 1], [0.85, 1])})` }}>
        <Img src={staticFile('brand/genovus-egg.svg')} style={{ width: 120 * u, height: 150 * u, transform: `scale(${pulse})` }} />
        <div style={{ fontFamily: F.display, fontWeight: 800, fontSize: 120 * u, color: '#fff', textTransform: 'uppercase', textAlign: 'center', lineHeight: 1.02, maxWidth: 2000 * u }}>{item.text}</div>
        <div style={{ padding: `${20 * u}px ${48 * u}px`, borderRadius: 999, background: ACCENT, fontFamily: F.display, fontWeight: 800, fontSize: 58 * u, color: '#111', letterSpacing: '0.04em' }}>{item.sub ?? 'GENOVUS.IO'}</div>
      </div>
      <LightLeak durationInFrames={Math.round(FPS * 1.2)} seed={9} hueShift={0} style={{ opacity: 0.28, mixBlendMode: 'screen' }} />
    </AbsoluteFill>
  );
}

/** A clip cue on a 9:16 stage: on the right of a landscape frame (the speaker keeps the center), or the full frame. */
function CueStage({ cue, dur }: { cue: ProCue; dur: number }) {
  const { width, height } = useVideoConfig();
  const landscape = width > height;
  const scale = landscape ? (height * 0.92) / 1920 : width / 1080;
  const left = landscape ? width - 1080 * scale - height * 0.05 : 0;
  return (
    <div style={{ position: 'absolute', left, top: landscape ? height * 0.04 : 0, width: 1080, height: 1920, transform: `scale(${scale})`, transformOrigin: 'top left' }}>
      <MovingBlur dur={dur}><CueGraphic cue={{ ...cue, t: 0, end: dur / FPS }} dur={dur} /></MovingBlur>
    </div>
  );
}

// ---- the style book's premium styles (HyperFrames blocks, src/hf) --------------------------------------------------
const chapterKicker = (n?: number) => `CHAPTER ${String(n ?? 1).padStart(2, '0')}`;
function BottomScrim({ dur }: { dur: number }) {
  const { t } = useT();
  return <Scrim side="bottom" amount={0.7} opacity={tw(t, 0, 0.3, E.p2Out) * (1 - tw(t, dur - 0.4, 0.4, E.p2In))} />;
}
/** A chapter change is a scene change: a short light leak sweeps across as the card arrives. */
const ChapterLeak = () => <LightLeak durationInFrames={Math.round(FPS * 0.9)} seed={3} hueShift={0} style={{ opacity: 0.32, mixBlendMode: 'screen' }} />;

/** The premium style for an item, or null to fall back to the classic look. `s` is seconds on screen. */
function Styled({ it, s }: { it: EpItem; s: number }): React.ReactElement | null {
  switch (it.style) {
    case 'title.calm': return <TitleCalm kicker={it.sub ?? ''} headline={it.text} dur={s} maxW={it.maxW} />;
    case 'title.prism': return <PrismTitle kicker={it.sub ? it.sub.toUpperCase() : undefined} title={it.text} dur={s} size={150} font={HF.serif} weight={400} italic y={0.3} bow={4} />;
    case 'lower.mask': return <LowerMaskReveal name={it.text} role={it.sub ?? ''} dur={s} egg />;
    case 'lower.underline': return <LowerAccentUnderline name={it.text} role={(it.sub ?? '').toUpperCase()} dur={s} font={HF.geist} upper={false} />;
    case 'chapter.calm': return <><ChapterLeak /><TitleCalm kicker={chapterKicker(it.n)} headline={it.text} dur={s} maxW={it.maxW} /></>;
    case 'chapter.prism-serif': return <><ChapterLeak /><PrismTitle kicker={chapterKicker(it.n)} title={it.text} dur={s} size={150} font={HF.serif} weight={400} italic y={0.3} bow={4} /></>;
    case 'chapter.prism-wide': return <><ChapterLeak /><PrismTitle kicker={chapterKicker(it.n)} title={it.text.toUpperCase()} dur={s} size={190} font={HF.wide} weight={800} y={0.28} /></>;
    case 'kinetic.center': return <><BottomScrim dur={s} /><KineticCenterBuild text={it.text} dur={s} size={120} accent={it.accent} y={0.8} font={HF.geist} weight={800} /></>;
    case 'emphasis.serif': return <EmphasisWord text={it.text} dur={s} top={150} left={-20} size={520} font={HF.serif} weight={400} italic upper={false} drift={-140} />;
    case 'end.cascade': return <BrandClose tagline={it.text} url={(it.sub ?? 'genovus.io').toLowerCase()} dur={s} />;
    case 'end.mark3d': return <ExtrudedMark dur={s} tagline={`${it.text} · ${(it.sub ?? 'genovus.io').toLowerCase()}`} />;
    default: return null;
  }
}

export const UneditEpisodeCues: React.FC<EpisodeCuesProps> = ({ items }) => {
  const { width, height } = useVideoConfig();
  const u = Math.min(width, height) / 1440; // designed at 2560×1440
  return (
    <AbsoluteFill style={{ backgroundColor: 'transparent' }}>
      {items.map((it, i) => {
        const from = Math.round(it.at * FPS);
        const dur = Math.max(10, Math.round(it.dur * FPS));
        return (
          <Sequence key={i} from={from} durationInFrames={dur} name={`${i} ${it.kind}`}>
            {it.style ? <AbsoluteFill><Styled it={it} s={dur / FPS} /></AbsoluteFill>
              : it.kind === 'title' ? <Title item={it} dur={dur} u={u} />
              : it.kind === 'lower' ? <Lower item={it} dur={dur} u={u} />
              : it.kind === 'chapter' ? <Chapter item={it} dur={dur} u={u} />
              : it.kind === 'end' ? <End item={it} dur={dur} u={u} />
              : it.cue ? <CueStage cue={it.cue} dur={dur} /> : null}
          </Sequence>
        );
      })}
    </AbsoluteFill>
  );
};
